/**
 * @summary Get all references
 */
export const getGetReferencesUrl = (params?: GetReferencesParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/references?${stringifiedParams}`
    : `/api/references`;
};

export const getReferences = async (
  params?: GetReferencesParams,
  options?: RequestInit,
): Promise<Reference[]> => {
  return customFetch<Reference[]>(getGetReferencesUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getGetReferencesQueryKey = (params?: GetReferencesParams) => {
  return [`/api/references`, ...(params ? [params] : [])] as const;
};

export const getGetReferencesQueryOptions = <
  TData = Awaited<ReturnType<typeof getReferences>>,
  TError = ErrorType<unknown>,
>(
  params?: GetReferencesParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getReferences>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetReferencesQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getReferences>>> = ({
    signal,
  }) => getReferences(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof getReferences>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetReferencesQueryResult = NonNullable<
  Awaited<ReturnType<typeof getReferences>>
>;
export type GetReferencesQueryError = ErrorType<unknown>;

/**
 * @summary Get all references
 */

export function useGetReferences<
  TData = Awaited<ReturnType<typeof getReferences>>,
  TError = ErrorType<unknown>,
>(
  params?: GetReferencesParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getReferences>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetReferencesQueryOptions(params, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}

